import * as THREE from 'three';
import { buildBridge, hangerLength, CABLE_SAMPLES } from '../src/bridge.js';

const opts = { span: 60, towerHeight: 18, sag: 10, hangers: 21 };

describe('buildBridge', () => {
  const bridge = buildBridge(opts);

  // Children order documented in src/bridge.js:
  // [0..1] towers, [2] deck, [3] cable line, [4..4+hangers-1] hangers
  // => total children = hangers + 4
  it('has children count equal to hangers + 4', () => {
    expect(bridge.children.length).toBe(opts.hangers + 4);
  });

  it('cable lowest sampled point is at x=0 with y=towerHeight-sag', () => {
    const cable = bridge.children[3];
    const pos = cable.geometry.getAttribute('position');
    let lowest = null;
    for (let i = 0; i < pos.count; i++) {
      const p = new THREE.Vector3().fromBufferAttribute(pos, i);
      if (!lowest || p.y < lowest.y) lowest = p;
    }
    expect(pos.count).toBe(CABLE_SAMPLES);
    expect(lowest.x).toBeCloseTo(0, 6);
    expect(lowest.y).toBeCloseTo(opts.towerHeight - opts.sag, 6);
  });

  it('cable endpoints meet the tower tops', () => {
    const cable = bridge.children[3];
    const pos = cable.geometry.getAttribute('position');
    const first = new THREE.Vector3().fromBufferAttribute(pos, 0);
    const last = new THREE.Vector3().fromBufferAttribute(pos, pos.count - 1);
    expect(first.x).toBeCloseTo(-opts.span / 2, 6);
    expect(first.y).toBeCloseTo(opts.towerHeight, 6);
    expect(last.x).toBeCloseTo(opts.span / 2, 6);
    expect(last.y).toBeCloseTo(opts.towerHeight, 6);
  });

  it('hangerLength is symmetric and strictly decreasing toward the middle', () => {
    const n = opts.hangers;
    for (let i = 0; i < n; i++) {
      expect(hangerLength(i, opts)).toBeCloseTo(
        hangerLength(n - 1 - i, opts),
        9
      );
    }
    for (let i = 0; i < Math.floor(n / 2); i++) {
      expect(hangerLength(i, opts)).toBeGreaterThan(hangerLength(i + 1, opts));
    }
  });

  it('each hanger mesh Box3 y-extent equals hangerLength(i)', () => {
    const box = new THREE.Box3();
    for (let i = 0; i < opts.hangers; i++) {
      const hanger = bridge.children[4 + i];
      box.setFromObject(hanger);
      const extent = box.max.y - box.min.y;
      expect(extent).toBeCloseTo(hangerLength(i, opts), 6);
      expect(hanger.userData.index).toBe(i);
    }
  });

  it('hangers connect deck top (y=0) to the cable', () => {
    const box = new THREE.Box3();
    for (let i = 0; i < opts.hangers; i++) {
      const hanger = bridge.children[4 + i];
      box.setFromObject(hanger);
      expect(box.min.y).toBeCloseTo(0, 6);
      const x = hanger.position.x;
      const expectedTop =
        opts.towerHeight - opts.sag * (1 - ((2 * x) / opts.span) ** 2);
      expect(box.max.y).toBeCloseTo(expectedTop, 6);
    }
  });
});
