result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/bridge.js", "content": "import * as THREE from 'three';

/**
 * Suspension bridge model.
 *
 * Scene-graph layout (children of the returned THREE.Group, in order):
 *   index 0             : tower at x = -span/2
 *   index 1             : tower at x = +span/2
 *   index 2             : deck box along x, centered at y = -deckThickness/2
 *                         (top surface at y = 0)
 *   index 3             : main cable as a THREE.Line polyline with
 *                         CABLE_SAMPLES points
 *   index 4 .. hangers+3: vertical hanger cylinders, left to right,
 *                         each with userData.index = i
 *
 * Total children count = hangers + 4.
 */

export const CABLE_SAMPLES = 200;
const DECK_THICKNESS = 1;
const DECK_WIDTH = 2;
const HANGER_RADIUS = 0.1;

/** Cable height above y = 0 at position x for the given parameters. */
function cableY(x, span, towerHeight, sag) {
  return towerHeight - sag * (1 - ((2 * x) / span) ** 2);
}

/** x position of hanger i (hangers evenly spaced across the span, inclusive). */
function hangerX(i, span, hangers) {
  return -span / 2 + (span * i) / (hangers - 1);
}

/**
 * Length of hanger i (0-indexed): the vertical distance from the deck top
 * surface (y = 0) up to the main cable. Longest at the towers, shortest at
 * mid-span; symmetric about the middle and strictly decreasing toward it.
 */
export function hangerLength(i, { span = 60, towerHeight = 18, sag = 10, hangers = 21 } = {}) {
  const x = hangerX(i, span, hangers);
  return cableY(x, span, towerHeight, sag);
}

export function buildBridge({ span = 60, towerHeight = 18, sag = 10, hangers = 21 } = {}) {
  const bridge = new THREE.Group();
  bridge.name = 'suspension-bridge';

  const steelMaterial = new THREE.MeshStandardMaterial({ color: 0x8d99ae });

  // Towers at x = ±span/2, rising from y = 0 to y = towerHeight.
  const towerGeometry = new THREE.BoxGeometry(DECK_WIDTH, towerHeight, DECK_WIDTH);
  for (const tx of [-span / 2, span / 2]) {
    const tower = new THREE.Mesh(towerGeometry, steelMaterial);
    tower.name = 'tower';
    tower.position.set(tx, towerHeight / 2, 0);
    bridge.add(tower);
  }

  // Deck box along x, centered at y = -DECK_THICKNESS/2 so its top is y = 0.
  const deck = new THREE.Mesh(
    new THREE.BoxGeometry(span + DECK_WIDTH, DECK_THICKNESS, DECK_WIDTH * 2),
    new THREE.MeshStandardMaterial({ color: 0x2b2d42 })
  );
  deck.name = 'deck';
  deck.position.set(0, -DECK_THICKNESS / 2, 0);
  bridge.add(deck);

  // Main cable: parabola sampled at CABLE_SAMPLES points from -span/2 to span/2.
  const cablePoints = [];
  for (let s = 0; s < CABLE_SAMPLES; s++) {
    const x = -span / 2 + (span * s) / (CABLE_SAMPLES - 1);
    cablePoints.push(new THREE.Vector3(x, cableY(x, span, towerHeight, sag), 0));
  }
  const cable = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(cablePoints),
    new THREE.LineBasicMaterial({ color: 0xd90429 })
  );
  cable.name = 'main-cable';
  bridge.add(cable);

  // Vertical hangers connecting deck top (y = 0) to the cable.
  for (let i = 0; i < hangers; i++) {
    const length = hangerLength(i, { span, towerHeight, sag, hangers });
    const hanger = new THREE.Mesh(
      new THREE.CylinderGeometry(HANGER_RADIUS, HANGER_RADIUS, length, 8),
      steelMaterial
    );
    hanger.name = 'hanger';
    hanger.userData.index = i;
    hanger.position.set(hangerX(i, span, hangers), length / 2, 0);
    bridge.add(hanger);
  }

  return bridge;
}
"})
